fn main() {
  io.println("╔══════════════════════╗");
  io.println("║  DIGITAL BUSINES CARD ║");
  io.println("╚══════════════════════╝");

  let name: Str = "Alex Rivera";
  let age: Int = 25;
  io.println("Name: ");
  io.println(name);
  io.println("Age: ");
  io.println(age);

  let birthday: Int = age + 1;
  io.println("Age next birthday: ");
  io.println(birthday);

  let lucky: Int = math.random_range(1, 100);
  io.println("Your lucky number: ");
  io.println(lucky);

  let fortune_roll: Int = math.random_range(1, 3);
  io.println("Fortune: ");
  if fortune_roll == 1 {
    io.println("You will write great code!");
  } elif fortune_roll == 2 {
    io.println("A bug-free day awaits you!");
  } else {
    io.println("Your functions will always compile!");
  }

  io.println("--- Skills ---");
  let skills = ["XIOM", "Variables", "Loops", "Strings", "Random"];
  for skill in skills {
    io.println("* ");
    io.println(skill);
  }

  let name_len: Int = string.str_len(name);
  io.println("Name character count: ");
  io.println(name_len);

  io.println("Thank you for completing Level 0!");
}
```

This program has it all — formatted output, variables, math, random numbers, if/elif/else branching, a for loop over a list, and string functions. Every concept from Level 0 is represented. You built this!

