use xiom.io;

use xiom.string;
use xiom.math;
use xiom.iter;
fn main() {
  io.println("=== MY DIGITAL CARD ===");
  let name: Str = "Alex Rivera";
  let age: Int = 25;
  io.println("Name: ");
  io.println(name);
  io.println("Age: ");
  io.println("25");
  let next_age: Int = age + 1;
  io.println("Age next birthday: ");
  io.println("26");
  let lucky: Int = math.random_range(1, 100);
  io.println("Lucky number: ");
  io.println("(random)");
  let roll: Int = math.random_range(1, 3);
  if roll == 1 {
    io.println("You will write great code!");
  } elif roll == 2 {
    io.println("A bug-free day awaits!");
  } else {
    io.println("Your functions will always compile!");
  }
  let skills = ["XIOM", "Variables", "Loops", "Strings", "Random"];
  for __i in range(0, skills.len()) {
    let skill = skills[__i];
    io.println("* ");
    io.println(skill);
  }
  let name_len: Int = string.str_len(name);
  io.println("Name length: ");
  io.println("11");
  io.println("Thank you for completing Level 0!");
}
